const same=(a,b)=>JSON.stringify(a)===JSON.stringify(b);const byId=(xs=[])=>new Map(xs.map(x=>[x.id,x]));
function unchanged(before,after,keys){for(const k of keys)if(!same(before[k],after[k]))throw Object.assign(new Error(`forbidden_prototype_field:${k}`),{status:403})}
function noDeletion(before,after,key){if((after[key]||[]).length<(before[key]||[]).length)throw Object.assign(new Error(`forbidden_prototype_deletion:${key}`),{status:403})}
function validateRequests(before,after,user,identity){const old=byId(before.requests),next=byId(after.requests);for(const [id,prev] of old){const cur=next.get(id);if(!cur)throw Object.assign(new Error('forbidden_request_deletion'),{status:403});if(same(prev,cur))continue;if(user.role==='parent'){if(prev.requestedBy!==identity.personId||!['cancelada',prev.status].includes(cur.status))throw Object.assign(new Error('forbidden_parent_request_change'),{status:403})}else if(user.role==='reception'){if(!['aprobada','rechazada','aceptada',prev.status].includes(cur.status))throw Object.assign(new Error('forbidden_reception_request_change'),{status:403})}else if(user.role==='gate'){if(!(prev.status==='aprobada'&&cur.status==='retirado'))throw Object.assign(new Error('forbidden_gate_request_change'),{status:403})}else if(user.role==='teacher')throw Object.assign(new Error('forbidden_teacher_request_change'),{status:403})}for(const [id,cur] of next)if(!old.has(id)&&user.role==='parent'&&cur.requestedBy!==identity.personId)throw Object.assign(new Error('forbidden_parent_request_owner'),{status:403})}
export function validatePrototypeMutation(before,after,user){if(!before||user.role==='admin')return true;if(!after||typeof after!=='object')throw Object.assign(new Error('invalid_state'),{status:400});const identity=user.prototypeIdentity||{};const immutable=['school','settings','routes','levels','staff','permissions','students'];unchanged(before,after,immutable);for(const key of ['requests','notifications','chats','chatState','log'])noDeletion(before,after,key);validateRequests(before,after,user,identity);
 if(user.role==='parent'){unchanged(before,after,['busTrips']);const oldPeople=byId(before.persons);for(const p of after.persons||[])if(oldPeople.has(p.id)&&!same(oldPeople.get(p.id),p))throw Object.assign(new Error('forbidden_person_change'),{status:403});for(const a of after.authorizations||[]){const prev=(before.authorizations||[]).find(x=>x.id===a.id);if(prev&&!same(prev,a)&&prev.createdBy!==identity.personId)throw Object.assign(new Error('forbidden_authorization_change'),{status:403});if(!prev&&a.createdBy!==identity.personId)throw Object.assign(new Error('forbidden_authorization_owner'),{status:403})}}
 if(user.role==='reception')unchanged(before,after,['persons','authorizations','busTrips']);if(user.role==='gate')unchanged(before,after,['persons','busTrips']);if(user.role==='teacher')unchanged(before,after,['persons','authorizations','busTrips']);if(user.role==='monitora')unchanged(before,after,['persons','authorizations']);return true}
